package app.kinnect.live;
import android.app.*;import android.os.*;import android.content.*;import android.graphics.*;import android.graphics.drawable.*;import android.view.*;import android.widget.*;import org.json.*;import java.util.*;

public class StoreActivity extends Activity implements StoreBilling.Events {
 @Override protected void attachBaseContext(Context base){super.attachBaseContext(I18n.localized(base));}
 private JSONObject catalog;private final Map<String,String> prices=new HashMap<>();private StoreBilling billing;private LinearLayout body;private String selectedTab="style";private boolean busy;private final java.util.ArrayDeque<String[]> receiptQueue=new java.util.ArrayDeque<>();
 private int dp(int value){return Math.round(value*getResources().getDisplayMetrics().density);}
 private String tr(String s){return I18n.t(s);}
 private int variant(){return WebTheme.isDark(this)?1:0;}
 private GradientDrawable round(int color,int radius){GradientDrawable d=new GradientDrawable();d.setColor(color);d.setCornerRadius(dp(radius));return d;}
 private TextView label(String text,int size){TextView v=new TextView(this);v.setText(text);v.setTextSize(size);v.setTypeface(ApprovedTypography.font(this,Typeface.NORMAL));v.setTextColor(WebDesign.INK[variant()]);v.setPadding(0,dp(5),0,dp(5));return v;}
 private Button button(String title,Runnable action){Button b=new Button(this);b.setText(title);b.setAllCaps(false);b.setTextSize(14);b.setTypeface(ApprovedTypography.font(this,Typeface.BOLD));b.setMinHeight(dp(48));b.setOnClickListener(v->action.run());return b;}
 private boolean owns(String id){JSONArray owned=catalog==null?null:catalog.optJSONArray("owned");if(owned!=null)for(int i=0;i<owned.length();i++)if(id.equals(owned.optString(i)))return true;return false;}
 public void onCreate(Bundle saved){super.onCreate(saved);NativeApi.shared.initialize(this,ServerConfig.DEFAULT_ORIGIN);billing=StoreBilling.create(this);load(true);}
 private void load(boolean connect){NativeApi.shared.call("GET","/api/store",null,(data,error,status)->{if(isFinishing()||isDestroyed())return;if(error!=null){message(error);if(catalog==null){LinearLayout page=new LinearLayout(this);page.setOrientation(1);page.setPadding(dp(20),dp(20),dp(20),dp(20));page.addView(label(tr("Chưa tải được cửa hàng."),18));page.addView(button(tr("Thử lại"),()->load(true)));page.addView(button(tr("Quay lại"),()->finish()));setContentView(page);}return;}catalog=data;draw();if(connect){List<String> ids=new ArrayList<>();JSONArray products=catalog.optJSONArray("products");for(int i=0;i<products.length();i++)ids.add(products.optJSONObject(i).optString("id"));billing.connect(ids,catalog.optString("accountId"),this);}});}
 private void draw(){
  LinearLayout root=new LinearLayout(this);root.setOrientation(1);root.setBackgroundColor(WebDesign.BG[variant()]);root.setOnApplyWindowInsetsListener((v,i)->{v.setPadding(0,i.getSystemWindowInsetTop(),0,i.getSystemWindowInsetBottom());return i;});setContentView(root);
  LinearLayout top=new LinearLayout(this);top.setGravity(Gravity.CENTER_VERTICAL);top.setPadding(dp(12),0,dp(12),0);top.addView(button("‹",()->finish()),new LinearLayout.LayoutParams(dp(48),dp(48)));TextView title=label(tr("Cửa hàng Kinnect"),22);title.setTypeface(null,Typeface.BOLD);top.addView(title,new LinearLayout.LayoutParams(0,-2,1));root.addView(top);
  ScrollView scroll=new ScrollView(this);body=new LinearLayout(this);body.setOrientation(1);body.setPadding(dp(20),dp(8),dp(20),dp(28));scroll.addView(body);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));
  body.addView(label(tr("Phong cách của bạn. Công cụ sáng tạo của bạn."),16));
  LinearLayout tabs=new LinearLayout(this);for(String key:new String[]{"style","studio","owned"}){String text=key.equals("style")?tr("Phong cách"):key.equals("studio")?"Studio Pro":tr("Đã sở hữu");Button tab=button(text,()->{selectedTab=key;draw();});tab.setSelected(selectedTab.equals(key));tabs.addView(tab,new LinearLayout.LayoutParams(0,-2,1));}body.addView(tabs);
  if(!catalog.optBoolean("billingReady")||!Distribution.PLAY)body.addView(label(tr("Cửa hàng đang chuẩn bị mở bán. Bạn có thể xem thử; chưa phát sinh thanh toán."),14));
  JSONArray products=catalog.optJSONArray("products");int shown=0;for(int i=0;i<products.length();i++){JSONObject p=products.optJSONObject(i);if(selectedTab.equals("owned")?!owns(p.optString("id")):!selectedTab.equals(p.optString("kind")))continue;shown++;product(p);}
  if(shown==0)body.addView(label(tr("Bạn chưa có sản phẩm nào trong mục này."),16));
  body.addView(button(tr("Khôi phục giao dịch"),()->{billing.restore();load(false);}));
  if(!catalog.optString("appearance").isEmpty())body.addView(button(tr("Dùng phong cách mặc định"),()->apply("")));
  body.addView(label(tr("Mua một lần cho tài khoản Kinnect hiện tại. Giá thanh toán do Google Play hiển thị. Đăng nhập cùng tài khoản để dùng quyền lợi trên thiết bị khác."),12));
 }
 private void product(JSONObject p){
  String id=p.optString("id");LinearLayout card=new LinearLayout(this);card.setOrientation(1);card.setPadding(dp(16),dp(16),dp(16),dp(16));card.setBackground(round(WebDesign.CARD[variant()],20));LinearLayout.LayoutParams space=new LinearLayout.LayoutParams(-1,-2);space.bottomMargin=dp(16);body.addView(card,space);
  JSONArray colors=p.optJSONArray("colors");View swatch=new View(this);GradientDrawable gradient=new GradientDrawable(GradientDrawable.Orientation.TL_BR,new int[]{Color.parseColor(colors.optString(0)),Color.parseColor(colors.optString(1))});gradient.setCornerRadius(dp(16));swatch.setBackground(gradient);card.addView(swatch,new LinearLayout.LayoutParams(-1,dp(74)));
  TextView name=label(p.optString("name"),20);name.setTypeface(null,Typeface.BOLD);card.addView(name);card.addView(label(p.optString(I18n.current().equals("en")?"descriptionEn":"description"),14));
  card.addView(button(tr("Xem thử"),()->new Sheet(this).setTitle(p.optString("name")).setMessage(p.optString(I18n.current().equals("en")?"descriptionEn":"description")+"\n\n"+tr("Xem thử không thay đổi hồ sơ hoặc cấp quyền sử dụng.")).setView(preview(p)).setPositiveButton(tr("Đóng"),null).show()));
  if(owns(id))card.addView(button(p.optString("kind").equals("style")?(id.equals(catalog.optString("appearance"))?tr("Đang sử dụng"):tr("Áp dụng")):tr("Mở Studio Pro"),()->{if(p.optString("kind").equals("style"))apply(id);else chooseMedia();}));
  else {String price=prices.get(id);Button buy=button(price==null?tr("Chưa mở bán"):tr("Mua một lần")+" · "+price,()->{if(!busy)billing.buy(id);});buy.setEnabled(price!=null&&catalog.optBoolean("billingReady")&&!busy);card.addView(buy);if(price==null)card.addView(label(tr("Giá dự kiến, chưa phải giá thanh toán")+": "+p.optInt("referenceVnd")+" VND",12));}
 }
 private View preview(JSONObject product){LinearLayout box=new LinearLayout(this);box.setOrientation(1);box.setPadding(dp(12),dp(12),dp(12),dp(12));JSONArray colors=product.optJSONArray("colors");int color=Color.parseColor(colors.optString(0));TextView demo=label(product.optString("kind").equals("studio")?"Aurora · Travel · Cinema":"Kinnect · "+tr("Hồ sơ minh họa"),22);demo.setTextColor(color);demo.setGravity(Gravity.CENTER);GradientDrawable frame=round(WebDesign.CARD[variant()],18);frame.setStroke(dp(3),color);demo.setPadding(dp(16),dp(18),dp(16),dp(18));demo.setBackground(frame);box.addView(demo);TextView chat=label(tr("Xin chào! Đây là bản xem thử."),16);chat.setTextColor(Color.WHITE);chat.setPadding(dp(16),dp(16),dp(16),dp(16));chat.setBackground(round(color,18));LinearLayout.LayoutParams at=new LinearLayout.LayoutParams(-1,-2);at.topMargin=dp(18);box.addView(chat,at);return box;}
 private void chooseMedia(){try{startActivityForResult(new Intent(Intent.ACTION_OPEN_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType("video/*"),700);}catch(Exception e){message(tr("Không mở được trình chọn video."));}}
 protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request==700&&result==RESULT_OK&&data!=null&&data.getData()!=null)startActivity(new Intent(this,MediaEditActivity.class).setData(data.getData()).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION).putExtra("store_pro",true));}
 private void apply(String id){try{NativeApi.shared.call("POST","/api/store/style",new JSONObject().put("productId",id),(data,error,status)->{if(error!=null)message(error);else{message(tr("Đã áp dụng phong cách."));load(false);}});}catch(Exception e){message(tr("Chưa áp dụng được phong cách."));}}
 public void prices(Map<String,String> value){runOnUiThread(()->{if(isDestroyed())return;prices.clear();prices.putAll(value);if(catalog!=null)draw();});}
 public void receipt(String product,String token){runOnUiThread(()->{if(isDestroyed())return;receiptQueue.add(new String[]{product,token});verifyNext();});}
 private void verifyNext(){if(busy||receiptQueue.isEmpty()||isDestroyed())return;busy=true;String[] receipt=receiptQueue.remove();try{NativeApi.shared.call("POST","/api/store/verify",new JSONObject().put("productId",receipt[0]).put("purchaseToken",receipt[1]),(data,error,status)->{busy=false;if(isDestroyed())return;message(error!=null?error:data.optString("state").equals("PURCHASED")?tr("Giao dịch đã xác minh. Quyền lợi đã được cập nhật."):tr("Giao dịch đang chờ xử lý; chưa cấp quyền lợi."));if(receiptQueue.isEmpty())load(false);else verifyNext();});}catch(Exception e){busy=false;message(tr("Chưa xác minh được giao dịch."));verifyNext();}}
 public void message(String text){runOnUiThread(()->{if(!isDestroyed())Toast.makeText(this,I18n.t(text),Toast.LENGTH_LONG).show();});}
 protected void onDestroy(){if(billing!=null)billing.close();super.onDestroy();}
}
